      "content": "{\n  \"name\": \"@eduwork/dsh-memory\",\n  \"version\": \"0.2.0\",\n  \"license\": \"MulanPSL-2.0 AND MIT\",\n  \"description\": \"Local memory and conversation recall for DeepSeek Harness\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./core\": \"./lib/core.js\",\n    \"./spec\": \"./lib/spec.js\",\n    \"./typert\": \"./lib/typert.host.js\",\n    \"./remote\": \"./lib/typert.remote-client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\"\n  },\n  \"files\": [\n    \"lib/**/*.js\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README_EN.md\",\n    \"docs/development.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\",\n    \"NOTICE\",\n    \"UPSTREAM.md\",\n    \"SECURITY.md\",\n    \"LICENSE-MIT\",\n    \"LICENSING.md\"\n  ],\n  \"scripts\": {\n    \"build\": \"node scripts/build.mjs\",\n    \"test\": \"node --test test/*.test.mjs\",\n    \"test:host\": \"node scripts/host-smoke.mjs\",\n    \"test:web\": \"node scripts/web-smoke.mjs\",\n    \"verify\": \"node scripts/verify.mjs\",\n    \"verify:runtime\": \"node scripts/verify-runtime.mjs\",\n    \"prepack\": \"npm run build\"\n  },\n  \"dsh\": {\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.5 <4.1.0\",\n    \"@deepseek-ai/dsh-api-remotes\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-commands\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-llm\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-settings\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-session-query\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-storage-domain\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-typert-protocol\": \">=0.2.1-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/schemastery\": \">=3.18.5 <3.19.0\",\n    \"react\": \"^18.2.0\",\n    \"zod\": \"^4.4.3\",\n    \"@deepseek-ai/dsh-storage-sqlite\": \">=0.2.1-rc.2 <0.3.0-0\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/ECNU/EduWork.git\",\n    \"directory\": \"packages/dsh-memory\"\n  },\n  \"homepage\": \"https://github.com/ECNU/EduWork/tree/main/packages/dsh-memory#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/ECNU/EduWork/issues\"\n  },\n  \"engines\": {\n    \"node\": \">=24.18.0\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh\": \"0.2.1-rc.2\",\n    \"esbuild\": \"0.25.9\",\n    \"playwright\": \"1.63.0\",\n    \"zod\": \"4.4.3\",\n    \"react\": \"18.3.1\",\n    \"@deepseek-ai/dsh-storage-sqlite\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"semver\": \"7.7.4\"\n  }\n}\n"
